 for(let i=0;i<p.links;i++){let prop=props[i],start=t,segments=[{label:'Truyền L/R',value:tx,tone:'orange'},{label:'Lan truyền d/s',value:prop,tone:'blue'}];rows.push({label:'Link '+(i+1),start,segments,bitPaths:{first:[start,start+prop],last:[start+tx,start+tx+prop]}});steps.push(step(`Link ${i+1}: bit đầu rời lúc ${f(start)} ms, tới lúc ${f(start+prop)} ms; bit cuối rời lúc ${f(start+tx)} ms, tới lúc ${f(start+tx+prop)} ms.`,{kind:'timeline',rows:structuredClone(rows),total,active:rows.length-1,markers:[{label:'Bit đầu tới',time:start+prop},{label:'Bit cuối tới',time:start+tx+prop}]}));t+=tx+prop;if(i===0&&(processing||queue)){rows.push({label:'Router',start:t,segments:[{label:'Xử lý',value:processing,tone:'green'},{label:'Hàng đợi',value:queue,tone:'red'}]});t+=processing+queue;steps.push(step(`Router xử lý ${f(processing)} ms, chờ ${f(queue)} ms. Store-and-forward: chỉ gửi tiếp sau khi nhận đủ bit cuối và hoàn tất xử lý/chờ.`,{kind:'timeline',rows:structuredClone(rows),total,active:rows.length-1}))}}
