const maps={protocol:['Định dạng thông điệp','Thứ tự gửi và nhận','Hành động khi nhận hoặc timeout','Protocol: quy tắc trao đổi chung'],osi:['7 Ứng dụng','6 Trình diễn','5 Phiên','4 Giao vận','3 Mạng','2 Liên kết dữ liệu','1 Vật lý'],addressClass:['Class B lịch sử: octet đầu 128–191','Private: 10/8 · 172.16/12 · 192.168/16','Loopback: toàn bộ 127/8','CIDR: dùng prefix đề cho, không suy mask từ lớp'],ttl:['Host gửi IP datagram TTL=1','Router giảm TTL một đơn vị','TTL thành 0: loại datagram','Có thể báo ICMP Time Exceeded về nguồn'],circuit:['Đặt tài nguyên trước phiên','TDM: chia khe thời gian','FDM: chia dải tần số','Tài nguyên dành riêng suốt phiên'],socket:['Tiến trình ứng dụng','Socket','TCP/UDP + port','IP + host'],services:['Ứng dụng: tin cậy / độ trễ','TCP: tin cậy, không bảo đảm thời hạn','UDP: không bảo đảm giao','IP: chuyển datagram best effort'],httpHeader:['Request: method · path · version','Header: Host / User-Agent','Dòng trống CRLF','Body dữ liệu (nếu có)','Response: status · Date · Last-Modified'],ipv6:['IPv6: địa chỉ 128 bit','Header cố định cơ sở 40 byte','Router không phân mảnh','Nguồn có thể dùng Fragment extension'],forwarding:['Địa chỉ IP đích','Tra bảng: longest prefix match','Chọn next hop / interface','Mạng Connected: gửi qua interface trực tiếp'],internet:['Các host trong mạng','Router / ISP trong một AS','IGP (RIP/OSPF) trong AS','BGP giữa các AS'],access:['Host','Ethernet / Wi-Fi / DSL / HFC / FTTH','Router biên','Internet'],topology:['LAN / MAN / WAN: phạm vi','Star / bus / ring / mesh: topology','Cáp / quang: có hướng dẫn','Vô tuyến: không dây'],concept:['Điều kiện trong câu hỏi','Thuật ngữ / quy tắc chuyên môn','Cơ chế đúng','Áp dụng vào tình huống']};let labels=maps[type]||maps.concept;nodes=labels.map((label,i)=>node('n'+i,label));let edges=['topology','addressClass','protocol','ipv6','circuit'].includes(type)?[]:nodes.slice(0,-1).map((n,i)=>edge(n.id,nodes[i+1].id));if(type==='services')edges=[edge('n0','n1'),edge('n0','n2'),edge('n1','n3'),edge('n2','n3')];return result(type,({protocol:'Protocol: cùng tuân theo quy tắc',osi:'OSI: bảy tầng',addressClass:'Phân lớp lịch sử, private & loopback',ttl:'TTL: dừng gói hết hạn',circuit:'Chuyển mạch kênh: TDM/FDM',socket:'Socket: phân kênh theo host & port',httpHeader:'Đọc cấu trúc HTTP',ipv6:'IPv6: đọc header & vai trò',services:'Ứng dụng chọn dịch vụ giao vận',forwarding:'Forwarding: tra bảng tuyến',topology:'Phân biệt phạm vi, topology và môi trường',access:'Mạng truy cập nối tới biên',internet:'Internet: trong AS và giữa AS'})[type]||title,p,nodes.map((n,i)=>step(n.label+'. '+(type==='socket'?'TCP dùng bộ địa chỉ/cổng để phân biệt kết nối; hai host khác nhau có thể trùng cổng nguồn.':'Các khối chỉ minh họa quan hệ; nhãn chuyên môn là cơ chế thực tế.'),graph(nodes,edges,[n.id]))),[],{},'Ví dụ tự tạo theo chủ đề PDF; vị trí và kích thước khối không theo tỷ lệ vật lý. Phần “Kết nối với câu này” bên dưới xác định đáp án và giải thích của đúng câu đang học.');
